    internal static int NtHexval(int c) {
        if ((c >= 48) && (c <= 57)) {
            return c - 48;
        }
        if ((c >= 65) && (c <= 70)) {
            return c - 55;
        }
        if ((c >= 97) && (c <= 102)) {
            return c - 87;
        }
        return -1;
    }
    internal static int NtCps(byte[] b, int from, int to, emon.Port.Cells c) {
        // Parse the hex numbers separated by spaces in b[from, to) into c,
        // cleared first. Answers how many.
        int k = from;
        int v = 0;
        int @in = 0;
        int d = 0;
        emon.Port.CellsDrop(c, 0);
        while (k < to) {
            d = NtHexval(emon.Port.BlobU8(b, k));
            if (d >= 0) {
                v = (v * 16) + d;
                @in = 1;
            } else if (@in == 1) {
                emon.Port.CellsPush(c, v);
                v = 0;
                @in = 0;
            }
            k += 1;
        }
        if (@in == 1) {
            emon.Port.CellsPush(c, v);
        }
        return emon.Port.CellsLen(c);
    }
    internal static int NtLit(byte[] b, emon.Port.Cells c) {
        // A whole text of hex code points, for the readable laws.
        return NtCps(b, 0, emon.Port.BlobLen(b), c);
    }
    internal static int NtSemi(byte[] b, int i, int lim) {
        int k = i;
        while ((k < lim) && (emon.Port.BlobU8(b, k) != 59)) {
            k += 1;
        }
        return k;
    }
    internal static int NtNl(byte[] b, int i) {
        int k = i;
        while ((k < emon.Port.BlobLen(b)) && (emon.Port.BlobU8(b, k) != 10)) {
            k += 1;
        }
        return k;
    }
    internal static int NtSame(emon.Port.Cells a, emon.Port.Cells b) {
        // 1 when the two code point runs are equal.
        int i = 0;
        if (emon.Port.CellsLen(a) != emon.Port.CellsLen(b)) {
            return 0;
        }
        while (i < emon.Port.CellsLen(a)) {
            if (emon.Port.CellsAt(a, i) != emon.Port.CellsAt(b, i)) {
                return 0;
            }
            i += 1;
        }
        return 1;
    }
